  "The team updates you on WhatsApp at each step.": "Das Team informiert Sie bei jedem Schritt per WhatsApp.",
  "Repairs you book on this device appear here with their job ticket.": "Reparaturen, die Sie auf diesem Gerät buchen, erscheinen hier mit ihrem Auftragsschein.",
  "Order": "Bestellung",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "Die Garantie jedes Teils steht auf Etikett und Rechnung; bringen Sie die Bestellnummer mit dem Teil mit.",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "Reparaturen sind ab dem Tag der Abholung garantiert. Bringen Sie diesen Schein mit.",
  "We can’t find that number on this account. Check it, or send it to us on WhatsApp and we look it up.": "Wir finden diese Nummer in diesem Konto nicht. Prüfen Sie sie oder senden Sie sie uns per WhatsApp.",
  "This browser cannot scan codes. Type the number instead.": "Dieser Browser kann keine Codes scannen. Bitte geben Sie die Nummer ein.",
