  "Your application": "Ihr Antrag",
  "Approved. Sign in and the shop shows your trade price on every part.": "Genehmigt. Melden Sie sich an, und der Shop zeigt bei jedem Teil Ihren Händlerpreis.",
  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "Wir antworten per E-Mail und WhatsApp, meist innerhalb eines Werktags. Melden Sie sich mit derselben E-Mail an, um das Ergebnis hier zu sehen.",
