  "Typical times for planning. Every shipment is quoted with its own time and price.": "Richtwerte zur Planung. Jede Sendung erhält ihre eigene Zeit und ihren Preis.",
  "CUSTOMS NOTES": "ZOLLHINWEISE",
  "LIVE ROUTES": "LIVE-ROUTEN",
  "Every week, out of Dubai.": "Jede Woche, ab Dubai.",
  "Planes on the air routes, ships on the sea lanes. Pick a region to see how we ship there.": "Flugzeuge auf den Luftrouten, Schiffe auf den Seewegen. Wählen Sie eine Region, um zu sehen, wie wir dorthin versenden.",
