  'WORLDWIDE SHIPPING': 'WELTWEITER VERSAND',
  'to your door.': 'bis an Ihre Tür.',
  'We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.': 'Wir versenden jede Woche Teile an Werkstätten und Händler im Nahen Osten, in Afrika, Europa und Asien: von Tür zu Tür mit unseren Partnern oder mit Ihrem eigenen Spediteur.',
