  'welcome too': 'ebenfalls willkommen',
  'WHERE WE SHIP': 'WOHIN WIR LIEFERN',
  'Pick a region, then tap a country to see how we get there and how long it takes.': 'Wählen Sie eine Region und tippen Sie auf ein Land, um zu sehen, wie wir liefern und wie lange es dauert.',
  'Tap a country for times': 'Land antippen für Lieferzeiten',
  'Get a quote': 'Angebot anfordern',
  'Same day to four weeks: you choose.': 'Vom selben Tag bis vier Wochen: Sie entscheiden.',
  'Every way we ship, on one line. Urgent parts fly; big orders sail.': 'Alle Versandarten auf einer Linie. Eilige Teile fliegen, große Bestellungen fahren per Schiff.',
  'Collect in Deira': 'Abholung in Deira',
  'You or your agent picks it up at our counter, same day.': 'Sie oder Ihr Vertreter holen es am selben Tag an unserer Theke ab.',
  'Express courier': 'Expresskurier',
  'Door to door with DHL, UPS, FedEx or Aramex. Urgent parts.': 'Von Tür zu Tür mit DHL, UPS, FedEx oder Aramex. Für eilige Teile.',
  'Road freight': 'Straßentransport',
  'By truck to Saudi Arabia, Oman and the Gulf.': 'Per Lkw nach Saudi-Arabien, Oman und in die Golfstaaten.',
  'Air cargo': 'Luftfracht',
  'Bulk orders to the main airports, best price per kilo.': 'Großbestellungen zu den Hauptflughäfen, bester Preis pro Kilo.',
  'About a week': 'Etwa eine Woche',
  'Sea freight': 'Seefracht',
  'Large orders by container, via Suez or East Africa.': 'Große Bestellungen per Container, über Suez oder Ostafrika.',
  'A commercial invoice and packing list go with every shipment.': 'Jeder Sendung liegen Handelsrechnung und Packliste bei.',
  'Duties and taxes are paid by the receiver on arrival, unless we agree otherwise.': 'Zölle und Steuern zahlt der Empfänger bei Ankunft, sofern nicht anders vereinbart.',
  'Some routes need the importer’s company registration for clearance; we tell you before we ship.': 'Manche Routen verlangen für die Verzollung die Firmenregistrierung des Importeurs; wir sagen es Ihnen vor dem Versand.',
  'Courier, air, road or sea: the best for your parts.': 'Kurier, Luft, Straße oder See: das Beste für Ihre Teile.',
  'It opens WhatsApp with your request, neatly laid out.': 'WhatsApp öffnet sich mit Ihrer Anfrage, übersichtlich aufbereitet.',
  'Shipping, time and paperwork, before you pay.': 'Versand, Dauer und Papiere, bevor Sie zahlen.',
