  'weeks': 'Wochen',
  'See every country': 'Alle Länder ansehen',
  'Our home market: next-day to the Gulf, a few days to the Levant.': 'Unser Heimatmarkt: am nächsten Tag am Golf, in wenigen Tagen in der Levante.',
  'From London to Kyiv: express, air cargo or sea via Suez.': 'Von London bis Kyjiw: Express, Luftfracht oder See über Suez.',
  'North, East and West Africa by courier, cargo or sea.': 'Nord-, Ost- und Westafrika per Kurier, Fracht oder See.',
  'India, Pakistan and the Caucasus, by air and by sea.': 'Indien, Pakistan und der Kaukasus, per Luft und per See.',
  'week': 'Woche',
  'Air cargo and express, from Dubai.': 'Luftfracht und Express, ab Dubai.',
  'Air cargo · China, Middle East': 'Luftfracht · China, Naher Osten',
  'Air freight from Dubai': 'Luftfracht ab Dubai',
  'Already have a cargo agent or a courier account? Send them to us. We pack your order, hand it over and share the paperwork.': 'Sie haben schon einen Frachtagenten oder ein Kurierkonto? Schicken Sie ihn zu uns. Wir packen Ihre Bestellung, übergeben sie und teilen die Papiere.',
  'Ask for a quote': 'Angebot anfordern',
  'City': 'Stadt',
  'Delivered to your door': 'Bis an Ihre Tür geliefert',
  'Door to door, by us': 'Von Tür zu Tür, durch uns',
  'Every part checked, packed for the trip.': 'Jedes Teil geprüft, reisefertig verpackt.',
  'Express door to door': 'Express von Tür zu Tür',
  'Express worldwide': 'Express weltweit',
