  'In the shop or on WhatsApp.': 'Im Shop oder über WhatsApp.',
  'Middle East & Africa': 'Naher Osten & Afrika',
  'Not on the list? We ship almost anywhere: ask us.': 'Nicht auf der Liste? Wir liefern fast überallhin: fragen Sie uns.',
  'OPTION 1': 'OPTION 1',
