  'OUR SHIPPING PARTNERS': 'UNSERE VERSANDPARTNER',
  'Order or send your list': 'Bestellen oder Liste schicken',
  'Our customers, around the world.': 'Unsere Kunden, rund um die Welt.',
  'Packed and tested': 'Verpackt und geprüft',
  'Partner names as given by the owner; logos added once permission is confirmed.': 'Partnernamen laut Inhaber; Logos folgen nach bestätigter Erlaubnis.',
  'Tell us where and what, and we quote the route and the price, usually the same day.': 'Sagen Sie uns wohin und was, und wir nennen Route und Preis, meist am selben Tag.',
  'Thank you!': 'Danke!',
  'Tracked all the way, customs paperwork handled.': 'Durchgehend verfolgt, Zollpapiere erledigt.',
  'We book the best route for your parcel: express for urgent parts, air cargo for bulk.': 'Wir buchen die beste Route für Ihr Paket: Express für Eiliges, Luftfracht für große Mengen.',
  'We help with packing and paperwork, but the shipping cost and the shipper’s terms are between you and your shipper.': 'Wir helfen bei Verpackung und Papieren, aber Versandkosten und Bedingungen klären Sie mit Ihrem Spediteur.',
  'We opened WhatsApp with your request; the team replies there.': 'Wir haben WhatsApp mit Ihrer Anfrage geöffnet; das Team antwortet dort.',
  'We quote shipping': 'Wir nennen die Versandkosten',
  'Weight, route and time, before you pay.': 'Gewicht, Route und Dauer, bevor Sie zahlen.',
  'What are you sending for?': 'Was sollen wir schicken?',
