  'Worldwide': 'Weltweit',
  'Your own shipper': 'Ihr eigener Spediteur',
  'e.g. 50 × iPhone 13 screens, 100 × A54 batteries': 'z. B. 50 × iPhone-13-Displays, 100 × A54-Akkus',
  'APPLICATION': 'BEWERBUNG',
  'Always open': 'Immer offen',
  'Any team': 'Jedes Team',
  'Apply for this role': 'Auf diese Stelle bewerben',
  'Covered': 'Abgesichert',
  'Every part is labelled by grade and maker, and tested before it leaves the shop.': 'Jedes Teil ist nach Qualitätsstufe und Hersteller gekennzeichnet und wird vor dem Versand geprüft.',
  'Fair prices for repair shops and traders, with trade prices for bulk.': 'Faire Preise für Werkstätten und Händler, mit Handelspreisen für große Mengen.',
  'Family, same management': 'Familie, gleiche Leitung',
  'First counter in Deira': 'Erste Theke in Deira',
  'Hiring': 'Wir stellen ein',
  'If a part fails, we stand behind it. The warranty is written on the label, not hidden.': 'Fällt ein Teil aus, stehen wir dafür ein. Die Garantie steht auf dem Etikett, nicht im Kleingedruckten.',
  'In progress': 'In Arbeit',
  'Like a phone, we got updates. Here is the log.': 'Wie ein Handy bekamen wir Updates. Hier ist das Protokoll.',
  'Moving to Al Murar': 'Umzug nach Al Murar',
  'Open positions': 'Offene Stellen',
  'Photo arrives with the owner’s pictures': 'Foto folgt mit den Bildern des Inhabers',
