  'Pick your phone and see every repair we do for it: the part in each grade, the fitting fee and the total, before you come in.': 'Wählen Sie Ihr Handy und sehen Sie jede Reparatur: das Teil in jeder Qualität, die Einbaugebühr und den Gesamtpreis, bevor Sie kommen.',
  'Every repair for the': 'Jede Reparatur für das',
  'Part price + fitting fee = your total. Prices are samples; the bench confirms the final price before starting.': 'Teilepreis + Einbaugebühr = Ihr Gesamtpreis. Preise sind Beispiele; die Werkstatt bestätigt den Endpreis vor Beginn.',
  'The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.': 'Die Gebühr richtet sich nach dem Teilepreis. Der Techniker kann sie je nach Teil und Aufwand anpassen und sagt es Ihnen immer vorher.',
