  'More…': 'Mehr…',
  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'Alles auf dieser Website und in ihren Systemen (Fotos, Designs, Texte, Preise und Daten) gehört Sam Electronics und ist durch das Urheberrecht der VAE geschützt, darunter das Bundesgesetz Nr. 38 von 2021. Ein Screenshot für dich selbst ist in Ordnung; Kopieren, Teilen oder Veröffentlichen ohne unsere schriftliche Erlaubnis nicht.',
  'Your connection says you are somewhere else than your device does. Prices, stock and delivery here depend on where you really are, and hiding your location goes against our terms of use. Please switch the VPN off for real prices and delivery times.': 'Deine Verbindung sagt, du bist woanders als dein Gerät. Preise, Bestand und Lieferung hängen davon ab, wo du wirklich bist, und das Verbergen deines Standorts verstößt gegen unsere Nutzungsbedingungen. Bitte schalte das VPN aus, um echte Preise und Lieferzeiten zu sehen.',
  'Prices and delivery depend on where you really are. Please switch the VPN off.': 'Preise und Lieferung hängen davon ab, wo du wirklich bist. Bitte schalte das VPN aus.',
  'Why am I seeing this?': 'Warum sehe ich das?',
  'Keeping it for yourself is fine; sharing or publishing it needs our permission.': 'Für dich behalten ist in Ordnung; Teilen oder Veröffentlichen braucht unsere Erlaubnis.',
