  'Reads photos': 'Liest Fotos',
  'A screenshot of Settings → About, or the box label': 'Ein Screenshot von Einstellungen → Info oder das Etikett der Verpackung',
  'Hands you to a person': 'Verbindet dich mit einem Menschen',
  'The team on WhatsApp or WeChat, with your chat': 'Das Team auf WhatsApp oder WeChat, mit deinem Chat',
  'Send Samsoom a screenshot': 'Schick Samsoom einen Screenshot',
