  'I read your photo: it is a': 'Ich habe dein Foto gelesen: Es ist ein',
  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'Ich sehe eine IMEI-Nummer auf dem Foto. Schick sie dem Team auf WhatsApp, dann finden sie das genaue Modell.',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'Ich habe genau hingesehen, aber kein Modell auf dem Foto gefunden. Am besten klappt ein Screenshot von Einstellungen → Über das Telefon, oder nenn mir einfach das Modell.',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'Ich kann Text auf Fotos lesen, aber hier finde ich kein Modell. Versuch das Etikett der Verpackung oder tipp das Modell, den Rest mache ich.',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'Schick mir ein Foto über den Kamera-Knopf: am besten einen Screenshot von Einstellungen → Über das Telefon oder das Etikett der Verpackung. Ich lese das Modell für dich.',
  'Settings → About phone → Model.': 'Einstellungen → Über das Telefon → Modell.',
  'Settings → About phone → All specs → Model.': 'Einstellungen → Über das Telefon → Alle Spezifikationen → Modell.',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'Wähle *#06# für die IMEI und schick sie uns: Wir finden das genaue Modell.',
  'Still about your': 'Immer noch zu deinem',
  'Tell me the part: screen, battery, camera or charging port.': 'Nenn mir das Teil: Display, Akku, Kamera oder Ladebuchse.',
  'Sure, for which model?': 'Klar, für welches Modell?',
  'Tell me the model and I’ll find it.': 'Nenn mir das Modell, ich finde es.',
  'Which one are you after?': 'Welches suchst du?',
  'good news, we have these': 'gute Nachricht, das haben wir',
  'this is on our shelf': 'das liegt bei uns im Regal',
  'Tap + to add one to your cart.': 'Tippe auf +, um eins in den Warenkorb zu legen.',
  'Want it fitted? Ask me for the repair price.': 'Soll es eingebaut werden? Frag mich nach dem Reparaturpreis.',
  'We’re in Al Murar, Deira, Dubai.': 'Wir sind in Al Murar, Deira, Dubai.',
  'Tap below for the map and directions.': 'Tippe unten für Karte und Wegbeschreibung.',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'Ruf im Laden an, schreib uns auf WhatsApp oder WeChat oder per E-Mail. Auf Instagram, TikTok und Facebook sind wir @samelectronics.uae.',
  'Every part has a warranty that depends on the grade:': 'Jedes Teil hat eine Garantie, die von der Qualität abhängt:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'Nenn mir Modell und Teil, z. B. „A54 Akku“ oder „iPhone 13 Display“, und ich zeige dir den Preis jeder Qualität.',
  'The dirham is pegged to the dollar, so this rate stays the same.': 'Der Dirham ist an den Dollar gekoppelt, der Kurs bleibt also gleich.',
