  'This page is on its way.': 'Diese Seite ist unterwegs.',
  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'Dieser Teil der Website ist noch im Aufbau. Bis dahin findest du alles Nötige auf der Startseite.',
  'Open Find My Part': 'Mein Teil finden öffnen',
