  '· sample data': '· Beispieldaten',
  'Battery drains fast': 'Akku entlädt sich schnell',
  'Screen · Original': 'Display · Original',
  'Welcome to My Bench.': 'Willkommen auf Meiner Werkbank.',
  'CHOOSE YOUR STORE': 'WÄHLE DEINEN SHOP',
  'Using this website': 'Nutzung dieser Website',
  'Law': 'Anwendbares Recht',
  'Brand names & trademarks': 'Markennamen & Warenzeichen',
  'Compatibility only': 'Nur zur Kompatibilität',
  'Original and compatible parts': 'Original- und kompatible Teile',
  'Four kinds, named after phone parts': 'Vier Arten, benannt nach Handyteilen',
  'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Contact: samelectronics.uae@gmail.com.': 'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Kontakt: samelectronics.uae@gmail.com.',
  'These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates ("Sam Electronics", "we"), in the shop, on this website, on WhatsApp or by phone.': 'Diese Bedingungen gelten für jeden Verkauf durch Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates („Sam Electronics“, „wir“), im Laden, auf dieser Website, über WhatsApp oder per Telefon.',
  'Prices, stock, delivery times and offers depend on where you are. Please do not hide your location (for example with a VPN) when you browse or order; if you do, what you see may not apply to you and we may ask you to confirm your location before we confirm an order.': 'Preise, Bestand, Lieferzeiten und Angebote hängen von deinem Standort ab. Bitte verberge deinen Standort nicht (zum Beispiel mit einem VPN), wenn du stöberst oder bestellst; sonst gilt das Angezeigte möglicherweise nicht für dich, und wir bitten dich eventuell, deinen Standort zu bestätigen, bevor wir eine Bestellung bestätigen.',
  'Everything on this website and in our systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by UAE copyright law (Federal Decree-Law No. 38 of 2021). You may keep a copy for your own reference; copying, sharing or publishing it needs our written permission.': 'Alles auf dieser Website und in unseren Systemen (Fotos, Designs, Texte, Preise und Daten) gehört Sam Electronics und ist durch das Urheberrecht der VAE geschützt (Bundesgesetzesdekret Nr. 38 von 2021). Du darfst eine Kopie für dich selbst behalten; Kopieren, Teilen oder Veröffentlichen erfordert unsere schriftliche Erlaubnis.',
  'Account details (name, e-mail, phone, password stored encrypted), company details you add, orders and invoices, messages you send us, Samsoom chats if you keep them with your account, and basic technical data (device, pages visited) to keep the site working.': 'Kontodaten (Name, E-Mail, Telefon, verschlüsselt gespeichertes Passwort), Firmendaten, die du hinzufügst, Bestellungen und Rechnungen, Nachrichten an uns, Samsoom-Chats, wenn du sie in deinem Konto behältst, sowie grundlegende technische Daten (Gerät, besuchte Seiten), damit die Website funktioniert.',
  'Ask for a copy, a correction or deletion of your data, or object to its use, using the privacy form on the contact page. We answer within 30 days, in line with the UAE personal data protection law.': 'Fordere über das Datenschutzformular auf der Kontaktseite eine Kopie, Berichtigung oder Löschung deiner Daten an oder widersprich ihrer Nutzung. Wir antworten innerhalb von 30 Tagen gemäß dem Datenschutzgesetz der VAE.',
  'Battery (essential, always on): your cart, language, sign-in and these choices. Kept until you clear them; sign-in until you sign out.': 'Akku (notwendig, immer aktiv): Warenkorb, Sprache, Anmeldung und diese Auswahl. Gespeichert, bis du sie löschst; die Anmeldung bis zum Abmelden.',
  'Memory Chip (preferences): currency, sounds, recent searches, starred parts and your devices. Kept 12 months.': 'Speicherchip (Präferenzen): Währung, Töne, letzte Suchen, gemerkte Teile und deine Geräte. 12 Monate gespeichert.',
  'Diagnostics (anonymous statistics): which pages are opened and how fast they load, never your name or contact. Kept 13 months.': 'Diagnose (anonyme Statistik): welche Seiten geöffnet werden und wie schnell sie laden, nie dein Name oder Kontakt. 13 Monate gespeichert.',
  'Antenna (marketing and offers): the kinds of parts you look at, to show matching offers. Kept 6 months.': 'Antenne (Marketing und Angebote): welche Arten von Teilen du ansiehst, um passende Angebote zu zeigen. 6 Monate gespeichert.',
  'The banner asks once, after the welcome. Change your choice any time with "Cookie settings" at the bottom of every page, or clear everything in your browser: the site will simply forget your cart and preferences on that device. Each choice is saved with its date.': 'Das Banner fragt einmal, nach der Begrüßung. Ändere deine Wahl jederzeit über „Cookie-Einstellungen“ unten auf jeder Seite oder lösche alles in deinem Browser: Die Website vergisst dann einfach Warenkorb und Einstellungen auf diesem Gerät. Jede Wahl wird mit Datum gespeichert.',
  'Brand names, model names and logos (such as Apple, Samsung, Xiaomi, Huawei and others) belong to their owners. We use them only to show which phones a part fits. Sam Electronics is an independent parts seller and repair shop, and is not affiliated with, authorised by or endorsed by these brands unless a page says so.': 'Markennamen, Modellnamen und Logos (etwa Apple, Samsung, Xiaomi, Huawei und andere) gehören ihren Inhabern. Wir verwenden sie nur, um zu zeigen, zu welchen Handys ein Teil passt. Sam Electronics ist ein unabhängiger Teilehändler und Reparaturbetrieb und steht in keiner Verbindung zu diesen Marken, ist nicht von ihnen autorisiert oder empfohlen, sofern eine Seite nichts anderes sagt.',
  'Every part is labelled with its quality and its maker. "Original" and "Service Pack" mean parts made for the brand; every other quality is a compatible part from the maker named on the label.': 'Jedes Teil ist mit Qualität und Hersteller gekennzeichnet. „Original“ und „Service Pack“ bedeuten Teile, die für die Marke gefertigt wurden; jede andere Qualität ist ein kompatibles Teil des auf dem Etikett genannten Herstellers.',
  'LIVE PARTS BOARD · LIVE FEED': 'LIVE-TEILETAFEL · LIVE-FEED',
  'REPAIR SHOP': 'WERKSTATT',
  'A54 OLED SCREEN': 'A54 OLED-DISPLAY',
  'Phone parts · repairs · trade prices': 'Handyteile · Reparaturen · Händlerpreise',
