  'Original screens on flagship phones': 'Original-Displays an Topmodellen',
  'Tell us when, we print your job card.': 'Sag uns wann, wir drucken deinen Auftragsschein.',
  'SHIPPING ORDER': 'VERSANDAUFTRAG',
  'Tap “Model Number” once: it changes to a code that starts with A (for example A2846).': 'Tippe einmal auf „Modellnummer“: Sie wird zu einem Code, der mit A beginnt (zum Beispiel A2846).',
  'Parts, repairs, trade, shipping and payments. Search, or pick a topic. Still stuck? Samsoom is one tap away.': 'Teile, Reparaturen, Handel, Versand und Zahlung. Suche oder wähle ein Thema. Noch Fragen? Samsoom ist einen Tipp entfernt.',
  'Pay your way.': 'Bezahle, wie du willst.',
  'Every way you can pay us today, in the shop, online and from abroad. Prices are in AED; card payments are charged in AED.': 'Alle Zahlungswege, die wir heute anbieten: im Laden, online und aus dem Ausland. Preise in AED; Kartenzahlungen werden in AED belastet.',
  'Online card payments go through a secure payment page; we never see or keep your card details.': 'Online-Kartenzahlungen laufen über eine sichere Zahlungsseite; wir sehen oder speichern deine Kartendaten nie.',
  'We never ask for your card number on WhatsApp or by e-mail.': 'Wir fragen nie per WhatsApp oder E-Mail nach deiner Kartennummer.',
  'Need another way to pay? Ask us on WhatsApp and we will tell you what is possible.': 'Brauchst du eine andere Zahlungsart? Frag uns auf WhatsApp, wir sagen dir, was möglich ist.',
  'When your internet connection says you are in a different place than your device’s clock, you are most likely using a VPN or a proxy.': 'Wenn deine Internetverbindung einen anderen Ort anzeigt als die Uhr deines Geräts, nutzt du höchstwahrscheinlich ein VPN oder einen Proxy.',
  'Prices, stock, delivery times and offers on this website depend on where you really are. With a hidden location, what you see may not apply to you, and we may ask you to confirm your location before we confirm an order.': 'Preise, Bestand, Lieferzeiten und Angebote auf dieser Website hängen davon ab, wo du wirklich bist. Mit verstecktem Standort gilt das Angezeigte vielleicht nicht für dich, und wir bitten dich eventuell, deinen Standort zu bestätigen, bevor wir eine Bestellung bestätigen.',
  'Our terms of use ask visitors not to hide their location when browsing or ordering. If you are simply travelling, choose “I am travelling” and carry on: nothing else changes.': 'Unsere Nutzungsbedingungen bitten Besucher, ihren Standort beim Stöbern oder Bestellen nicht zu verbergen. Wenn du einfach unterwegs bist, wähle „Ich bin auf Reisen“ und mach weiter: Sonst ändert sich nichts.',
  'We only compare two time zones. We never store your IP address.': 'Wir vergleichen nur zwei Zeitzonen. Deine IP-Adresse speichern wir nie.',
  'Browsers can only see the screenshot keys on computers (Print Screen, ⌘⇧3/4/5, Win+Shift+S). When we see one, this notice appears once and the team is told which page it was.': 'Browser erkennen Screenshot-Tasten nur am Computer (Druck, ⌘⇧3/4/5, Win+Umschalt+S). Wenn wir eine sehen, erscheint dieser Hinweis einmal, und das Team erfährt, welche Seite es war.',
  'If you took it for another reason, you can safely ignore the notice. For permission, write to us from the Contact page.': 'Wenn du ihn aus einem anderen Grund gemacht hast, kannst du den Hinweis einfach ignorieren. Für eine Erlaubnis schreib uns über die Kontaktseite.',
