  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'Shop-Werbefilm: Displays, jede Qualität, Akku-Woche, Händlerpreise, weltweiter Versand.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'Die große Box zeigt unsere neuesten Angebote. Wähle einen Tab, ein Teil oder eine Marke, und sie zeigt genau dazu passende Deals.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'Das farbige Etikett ist die Qualität (Original, OLED, Incell, AAA und mehr). Das dunkle mit dem Licht zeigt den Hersteller.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Markiere ein Teil, um es in My Bench zu behalten. Die Zwei-Karten-Taste fügt es zum Vergleich hinzu: bis zu drei Teile nebeneinander.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Nach Preis, Neuheit oder bester Übereinstimmung sortieren und zwischen Raster und Liste wechseln.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Werkstätten und Händler: einmal bewerben, und jedes Teil zeigt deinen Händlerpreis.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'Die häufigsten Fragen, an einem Ort beantwortet. Noch Fragen? Frag Samsoom.',
