  'Sure, let us find your order. I opened the order tracker below.': 'Klar, finden wir deine Bestellung. Unten ist der Bestell-Tracker offen.',
  'Happy to book you in. Pick the problem, a day and a time below.': 'Gern buche ich dich ein. Wähle unten Problem, Tag und Uhrzeit.',
  'I can watch that for you. Find the part below and I will ring the bell when it is back.': 'Ich behalte das für dich im Blick. Such das Teil unten, ich läute, sobald es wieder da ist.',
  'I can watch the price for you. Find the part below.': 'Ich beobachte den Preis für dich. Such das Teil unten.',
  'Let us check what fits. Tell me your phone below.': 'Prüfen wir, was passt. Nenn mir unten dein Handy.',
  'Paste your parts list below, one part per line.': 'Füge unten deine Teileliste ein, ein Teil pro Zeile.',
  'Parts that fit your': 'Teile, die passen zu deinem',
