  'COMPLAINTS': 'BESCHWERDEN',
  'Something went wrong?': 'Ist etwas schiefgelaufen?',
  'Tell us everything.': 'Erzähl uns alles.',
  'Every complaint gets a case number and goes straight to the management team. We answer within one working day.': 'Jede Beschwerde bekommt eine Fallnummer und geht direkt an die Geschäftsleitung. Wir antworten innerhalb eines Werktags.',
