  'Build a price list, then send or add it to the cart': 'Preisliste erstellen, dann senden oder in den Warenkorb',
  'A real person, right on the website': 'Ein echter Mensch, direkt auf der Website',
  'Fastest for stock, prices and orders': 'Am schnellsten für Bestand, Preise und Bestellungen',
  'Add our number and send a message': 'Nummer speichern und Nachricht senden',
  'Wrong answer': 'Falsche Antwort',
