  'Did not understand me': 'Hat mich nicht verstanden',
  'Search the questions': 'Fragen durchsuchen',
  'No question matches. Ask Samsoom instead.': 'Keine passende Frage. Frag stattdessen Samsoom.',
  'File a complaint: every case gets a number and goes to the management team.': 'Beschwerde einreichen: Jeder Fall bekommt eine Nummer und geht an die Geschäftsleitung.',
  'Out of stock · request it': 'Nicht vorrätig · anfragen',
  'left (estimate)': 'übrig (geschätzt)',
  'Requested': 'Angefragt',
  'Which screen grade?': 'Welche Display-Qualität?',
  'Ask us for this grade': 'Frag uns nach dieser Qualität',
  'Type your model, e.g. A54': 'Modell eingeben, z. B. A54',
  'No model matches. Ask Samsoom and we will check.': 'Kein Modell passt. Frag Samsoom, wir prüfen es.',
  'Phone or WhatsApp': 'Telefon oder WhatsApp',
  'Repair shops and traders paste a whole parts list and get it priced and checked against stock in one go, with trade prices.': 'Werkstätten und Händler fügen eine ganze Teileliste ein und bekommen sie auf einmal bepreist und mit dem Bestand abgeglichen, zu Händlerpreisen.',
  'Add your phone under My devices and the shop marks every part that fits. Not sure of your model? Use Find My Part, ask Samsoom, or send him a photo of Settings → About.': 'Füge dein Handy unter Meine Geräte hinzu, dann markiert der Shop jedes passende Teil. Modell unklar? Nutze Find My Part, frag Samsoom oder schick ihm ein Foto von Einstellungen → Info.',
  'Tip: send the team a photo of the label on the old part and they will match it for you.': 'Tipp: Schick dem Team ein Foto vom Etikett des alten Teils, sie finden das passende.',
  'Tip: bring the phone with the battery above 20% so the team can test it straight away.': 'Tipp: Bring das Handy mit über 20 % Akku, damit das Team es sofort testen kann.',
  'Tip: trade accounts see trade prices on every part once approved.': 'Tipp: Händlerkonten sehen nach Freigabe bei jedem Teil den Händlerpreis.',
  'Settings → General → About → Model Number. Tap it once to see the A-number (e.g. A2633). Or read it on the SIM tray slot.': 'Einstellungen → Allgemein → Info → Modellnummer. Einmal antippen für die A-Nummer (z. B. A2633). Oder am SIM-Schacht ablesen.',
  'Settings → About phone → Model number (SM-A546B…). Also on the box label.': 'Einstellungen → Telefoninfo → Modellnummer (SM-A546B…). Auch auf dem Karton-Etikett.',
  'Settings → About phone → Model (e.g. GD1YQ).': 'Einstellungen → Telefoninfo → Modell (z. B. GD1YQ).',
  'Shop here': 'Hier einkaufen',
  'Shopping here': 'Hier eingekauft',
  'Pick up today · ready in 20 minutes': 'Heute abholen · in 20 Minuten bereit',
  'See all notifications': 'Alle Benachrichtigungen',
  'not matched': 'nicht gefunden',
  'Removed from': 'Entfernt aus',
  'Added to': 'Hinzugefügt zu',
  'FRAMES': 'RAHMEN',
  'Screens, batteries, flex cables and every small part, for every popular model. Tested, graded and ready at the counter in Deira, or shipped to your door.': 'Displays, Akkus, Flexkabel und jedes Kleinteil für jedes gängige Modell. Getestet, eingestuft und bereit am Tresen in Deira oder bis vor deine Tür geliefert.',
  'Original is the part the phone maker fits. Compatible is made by a third party to fit and work like it. Standard is everyday quality at a fair price. AAA is a high-grade copy close to the original, and AA a step under it. OLED Soft, OLED Big and OLED Small are OLED screens (flexible, full-size or compact panels). Incell is an LCD with the touch built in, the budget choice. Other means a quality we source on request. Every part shows its grade as a coloured tag.': 'Original ist das Teil, das der Hersteller verbaut. Compatible stammt von einem Drittanbieter und passt und funktioniert genauso. Standard ist Alltagsqualität zum fairen Preis. AAA ist eine hochwertige Kopie nah am Original, AA eine Stufe darunter. OLED Soft, OLED Big und OLED Small sind OLED-Displays (flexible, große oder kompakte Panels). Incell ist ein LCD mit integriertem Touch, die günstige Wahl. Other ist eine Qualität, die wir auf Anfrage besorgen. Jedes Teil zeigt seine Qualität als farbiges Etikett.',
  'New medal': 'Neue Medaille',
  'I will show you the useful tools here. It takes 20 seconds.': 'Ich zeige dir die nützlichen Werkzeuge hier. Dauert 20 Sekunden.',
  'The message': 'Die Nachricht',
