  'Screenshots are for your own use only, for example to remember a part or to send it to your technician.': 'Screenshots sind nur für dich selbst, zum Beispiel um dir ein Teil zu merken oder es deinem Techniker zu schicken.',
  'Publishing, reselling or editing them, or using our photos and prices elsewhere, needs our written permission.': 'Veröffentlichen, Weiterverkaufen oder Bearbeiten sowie die Nutzung unserer Fotos und Preise anderswo braucht unsere schriftliche Erlaubnis.',
