  'Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp or WeChat the second you need one.': 'Samsoom kennt unseren Katalog, die Qualitätsstufen, Öffnungszeiten und den Versand. Er findet das Teil, erklärt die Qualität und verbindet dich sofort mit einem Menschen auf WhatsApp oder WeChat, wenn du einen brauchst.',
